import random

SIZE = 8
TYPES = 6


class Board:
    """Match-3 grid: matching, swapping, gravity and refills."""

    def __init__(self, size=SIZE, types=TYPES, seed=None):
        self.size = size
        self.types = types
        self.rng = random.Random(seed)
        self.grid = [[0] * size for _ in range(size)]
        self._fill()

    def in_bounds(self, r, c):
        return 0 <= r < self.size and 0 <= c < self.size

    @staticmethod
    def adjacent(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1

    def swap(self, a, b):
        (r1, c1), (r2, c2) = a, b
        self.grid[r1][c1], self.grid[r2][c2] = self.grid[r2][c2], self.grid[r1][c1]

    def matches(self):
        hits = set()
        n = self.size
        for r in range(n):
            for c in range(n - 2):
                t = self.grid[r][c]
                if t is not None and t == self.grid[r][c + 1] == self.grid[r][c + 2]:
                    hits.update(((r, c), (r, c + 1), (r, c + 2)))
        for c in range(n):
            for r in range(n - 2):
                t = self.grid[r][c]
                if t is not None and t == self.grid[r + 1][c] == self.grid[r + 2][c]:
                    hits.update(((r, c), (r + 1, c), (r + 2, c)))
        return hits

    def clear(self, cells):
        for r, c in cells:
            self.grid[r][c] = None

    def collapse(self):
        """Drop candies into holes and refill from the top."""
        moved = False
        for c in range(self.size):
            col = [self.grid[r][c] for r in range(self.size) if self.grid[r][c] is not None]
            missing = self.size - len(col)
            if missing:
                moved = True
            col = [self.rng.randrange(self.types) for _ in range(missing)] + col
            for r in range(self.size):
                self.grid[r][c] = col[r]
        return moved

    def has_move(self):
        n = self.size
        for r in range(n):
            for c in range(n):
                for dr, dc in ((0, 1), (1, 0)):
                    r2, c2 = r + dr, c + dc
                    if r2 < n and c2 < n:
                        a, b = (r, c), (r2, c2)
                        self.swap(a, b)
                        ok = bool(self.matches())
                        self.swap(a, b)
                        if ok:
                            return True
        return False

    def _fill(self):
        while True:
            for r in range(self.size):
                for c in range(self.size):
                    self.grid[r][c] = self.rng.randrange(self.types)
            hits = self.matches()
            while hits:
                for r, c in hits:
                    self.grid[r][c] = self.rng.randrange(self.types)
                hits = self.matches()
            if self.has_move():
                return

    def shuffle(self):
        """Reshuffle in place until the board is match-free and playable."""
        while True:
            flat = [t for row in self.grid for t in row]
            self.rng.shuffle(flat)
            for i, t in enumerate(flat):
                self.grid[i // self.size][i % self.size] = t
            if not self.matches() and self.has_move():
                return
